diff --git a/lib/src/cli/agent_cli_theme.dart b/lib/src/cli/agent_cli_theme.dart
index c94b76cf..abb310b0 100644
--- a/lib/src/cli/agent_cli_theme.dart
+++ b/lib/src/cli/agent_cli_theme.dart
@@ -81,12 +81,27 @@ extension ThemeCommands on AgentCli {
   Future<void> bootThemeForTest() => _applyBootTheme();

   /// Applies the persisted `tui.theme` at boot: user themes load first so
-  /// a persisted user theme resolves end to end (AC4). No persist
+  /// a persisted user theme resolves end to end (AC4). With NO explicit
+  /// `tui.theme`, the auto light/dark tier runs (issue #804 AC1.2):
+  /// COLORFGBG decides here — the TUI's OSC 11 reply re-resolves later
+  /// via [FaThemeController.reapplyAutoLightDark]. No persist
   /// round-trip.
   Future<void> _applyBootTheme() async {
     await _reloadUserThemes();
     final persisted = config.tuiTheme;
-    if (persisted == null || persisted.isEmpty) return;
+    if (persisted == null || persisted.isEmpty) {
+      // Auto tier (issue #804 AC1.2) — TUI sessions only: the TUI owns the
+      // OSC 11 re-check, and line mode must stay byte-unchanged (its
+      // COLORFGBG-light sessions keep today's palette). Dark resolves to
+      // the default palette (dark-terminal sessions keep today's bytes),
+      // light to ohmypi-light.
+      if (_useTui) {
+        FaThemeController.instance.armAutoLightDark(
+          colorfgbg: environment['COLORFGBG'],
+        );
+      }
+      return;
+    }
     if (!FaThemeController.instance.switchTo(persisted)) {
       io.writeln(
         'config tui.theme: unknown theme "$persisted" — using default '
diff --git a/lib/src/cli/fa_tui.dart b/lib/src/cli/fa_tui.dart
index c0a5d5d2..e362186e 100644
--- a/lib/src/cli/fa_tui.dart
+++ b/lib/src/cli/fa_tui.dart
@@ -790,6 +790,10 @@ final class FaTuiModel extends Model {
     // output and skip its render. The host's delayed _QuitRequestedMsg is
     // the only quit path that matters.
     if (msg is BusyMsg) return _handleBusyMsg(msg);
+    // Issue #804: the vendored program's OSC 11 background reply lands
+    // before the exit check — a late reply must still re-resolve the
+    // palette (and paint via the theme-swap cache reset) even while busy.
+    if (msg is BackgroundColorMsg) return _handleBackgroundProbe(msg);
     if (msg is RunStalledMsg) return _handleRunStalled(msg);
     if (msg is SpinnerTickMsg) return _handleSpinnerTick();
     if (msg is DrainQueueMsg) return _handleDrainQueue(msg);
diff --git a/lib/src/cli/fa_tui_rows.dart b/lib/src/cli/fa_tui_rows.dart
index bd3e1fac..feab0d02 100644
--- a/lib/src/cli/fa_tui_rows.dart
+++ b/lib/src/cli/fa_tui_rows.dart
@@ -125,7 +125,7 @@ extension _TuiRowRenderers on FaTuiModel {
   /// selected").
   String _rearmSelection(String label) {
     final theme = FaThemeController.instance;
-    final open = theme.sgrPrefix(theme.current.accent);
+    final open = theme.accentSgr();
     if (open.isEmpty) return label;
     if (!label.contains('\x1b[0m')) return '$open$label\x1b[0m';
     return label.replaceAll('\x1b[0m', '\x1b[0m$open');
diff --git a/lib/src/cli/fa_tui_theme_swap.dart b/lib/src/cli/fa_tui_theme_swap.dart
index 2ed84189..eaaabf48 100644
--- a/lib/src/cli/fa_tui_theme_swap.dart
+++ b/lib/src/cli/fa_tui_theme_swap.dart
@@ -25,6 +25,23 @@ extension FaTuiThemeSwap on FaTuiModel {
       .._stickyFmtWidth = null;
     return (next, null);
   }
+
+  /// OSC 11 background reply (issue #804): the vendored program probes
+  /// the terminal background at startup and the decoded color arrives
+  /// here. While the auto light/dark tier is armed (no explicit
+  /// `tui.theme`), the reply re-resolves the palette — a light terminal
+  /// upgrades the boot default to `ohmypi-light` right after the first
+  /// frame; dark keeps it (no swap, no repaint).
+  (Model, Cmd?) _handleBackgroundProbe(BackgroundColorMsg msg) {
+    final controller = FaThemeController.instance;
+    controller.measuredTerminalBg = RgbColor(
+      (msg.rgb >> 16) & 0xff,
+      (msg.rgb >> 8) & 0xff,
+      msg.rgb & 0xff,
+    );
+    if (!controller.reapplyAutoLightDark()) return (this, null);
+    return _handleThemeSwapped();
+  }
 }

