    RgbColor? bgOf(Style style) => style.backgroundRgb;

    test('reference terminal backgrounds split dark and light palettes', () {
      expect(
        themeReferenceTerminalBg(kBuiltInTuiThemes['ohmypi-light']!),
        const RgbColor(255, 255, 255),
