/// dart_tui `Theme` lacks the #444 roles, so fah vendors its extension.
export 'tui_theme_palette.dart';

/// The symbol presets (issue #804): glyphs + spinner frames, keyed like
/// omp's symbol map.
export 'tui_symbols.dart';

