const Map<String, TuiTheme> kBuiltInTuiThemes = {
  'default': kDefaultTuiTheme,
  'catppuccin': TuiTheme.catppuccin,
  'nord': TuiTheme.nord,
  'dracula': TuiTheme.dracula,
