List<Msg> _decodeX10Mouse(int cbByte, int cxByte, int cyByte) {
  final cb = cbByte - 32;
  final mouse = Mouse(
    x: cxByte >= 33 ? cxByte - 33 : 0,
    y: cyByte >= 33 ? cyByte - 33 : 0,
    button: cb == 3 ? MouseButton.none : _mouseButtonFromCb(cb),
    modifiers: _mouseModifiersFromCb(cb),
