  toolOutput: Style(foregroundRgb: RgbColor(0xB8, 0xC2, 0xCE), isDim: true),
  userMessageText: Style(foregroundRgb: RgbColor(0xE8, 0xEE, 0xF7)),
  toolSuccessBg: Style(backgroundRgb: RgbColor(20, 37, 27)),
