    t.highlight,
    t.success,
    t.warning,
    t.error,
    t.border,
    t.focusBorder,
    t.accent2,
    t.accent2Soft,
    t.userMessageBg,
    t.borderMuted,
    t.toolTitle,
    t.toolOutput,
