  accent2Soft: Style(foregroundRgb: RgbColor(0xb2, 0x81, 0xd6)),
  userMessageBg: Style(backgroundRgb: RgbColor(0x22, 0x1d, 0x1a)),
  // #804 parity: omp `borderMuted` is the darkGray var (#3d424a); the old
